import{_ as a,H as n,f as e,i as t}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"04 | 大模型AI智能体开发的3个层次：应用，微调和专有模型","description":"","frontmatter":{},"headers":[{"level":2,"title":"应用开发","slug":"应用开发","link":"#应用开发","children":[{"level":3,"title":"温度（Temperature）","slug":"温度-temperature","link":"#温度-temperature","children":[]},{"level":3,"title":"提示词工程","slug":"提示词工程","link":"#提示词工程","children":[]},{"level":3,"title":"逻辑控制","slug":"逻辑控制","link":"#逻辑控制","children":[]},{"level":3,"title":"架构图 V1","slug":"架构图-v1","link":"#架构图-v1","children":[]}]},{"level":2,"title":"模型微调","slug":"模型微调","link":"#模型微调","children":[{"level":3,"title":"什么是微调（Fine-tuning）？","slug":"什么是微调-fine-tuning","link":"#什么是微调-fine-tuning","children":[]},{"level":3,"title":"向量数据库 VS 微调","slug":"向量数据库-vs-微调","link":"#向量数据库-vs-微调","children":[]},{"level":3,"title":"架构图 V2","slug":"架构图-v2","link":"#架构图-v2","children":[]}]},{"level":2,"title":"专有模型开发","slug":"专有模型开发","link":"#专有模型开发","children":[{"level":3,"title":"行业大模型","slug":"行业大模型","link":"#行业大模型","children":[]},{"level":3,"title":"插件开发","slug":"插件开发","link":"#插件开发","children":[]},{"level":3,"title":"架构图V3","slug":"架构图v3","link":"#架构图v3","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"AI大模型项目落地实战/04｜大模型AI智能体开发的3个层次：应用，微调和专有模型.md","filePath":"AI大模型项目落地实战/04｜大模型AI智能体开发的3个层次：应用，微调和专有模型.md","lastUpdated":1795453306000}'),i={name:"AI大模型项目落地实战/04｜大模型AI智能体开发的3个层次：应用，微调和专有模型.md"};function p(l,s,E,h,o,r){return n(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="_04-大模型ai智能体开发的3个层次-应用-微调和专有模型" tabindex="-1">04 | 大模型AI智能体开发的3个层次：应用，微调和专有模型 <a class="header-anchor" href="#_04-大模型ai智能体开发的3个层次-应用-微调和专有模型" aria-label="Permalink to &quot;04 | 大模型AI智能体开发的3个层次：应用，微调和专有模型&quot;">​</a></h1><p>你好，我是金伟。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>对于咱们开发者来说，在本地体验大模型，相当于写一个 hello world 程序，没什么难</span></span></code></pre></div><p>度。那这节课，我们就讨论讨论大模型 AI 智能体开发过程里更多的一些挑战。</p><p>接触过一些大模型知识的朋友都听过一个词，大模型幻觉，指的是大模型有一定概率会胡编乱造。比如你问它桃园三兄弟“刘备、关羽、赵云”是怎么先后战死的啊？很明显，这问题就是错误的。但是大模型还会沿着错误一本正经地发挥。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/1.png" alt=""></a></p><p>我们介绍过，Transformer 架构是基于概率输出内容，这是大模型产生幻觉的原因。然而幻觉并不一定就意味着是坏事，没有幻觉的大模型不可能具有创造性，对吧？做大模型 AI 智能体开发，本质上就是如何尽量提高大模型的创造性，同时避免大模型出现偏差错误的过程。</p><p>我把大模型 AI 智能体开发由浅入深分为三个层次，应用开发、微调开发和专有模型开发。这节课，我们就把这三个层次分别都是什么，需要做什么给讲清楚。</p><h2 id="应用开发" tabindex="-1">应用开发 <a class="header-anchor" href="#应用开发" aria-label="Permalink to &quot;应用开发&quot;">​</a></h2><p>想要了解清楚大模型在应用开发中的角色，我们需要先从传统的互联网开发架构谈起。如下图所示，传统的互联网开发架构分为数据库层、应用层和用户终端层。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/2.png" alt=""></a></p><p>加入大模型之后的应用架构应该是什么样的呢？我们需要进一步分析。上图中的 LLM 表示大模型，在真实应用开发中，指的就是一个公开提供服务的大模型平台。</p><h3 id="温度-temperature" tabindex="-1">温度（Temperature） <a class="header-anchor" href="#温度-temperature" aria-label="Permalink to &quot;温度（Temperature）&quot;">​</a></h3><p>我在第二节课提到，训练完的大模型可以看做一个全功能的“人”。那怎么才能让这个“人”干活呢？其实很简单，通过一个接口就可以调用大模型，以讯飞星火大模型 3.5 的 Python 接口为例，先看它的具体实现代码。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>from sparkai.llm.llm import ChatSparkLLM, ChunkPrintHandler</span></span>
<span class="line"><span>from sparkai.core.messages import ChatMessage</span></span>
<span class="line"><span>#星火认知大模型Spark Max的URL值，其他版本大模型URL值请前往文档（https://www.xfyun.cn/doc/</span></span>
<span class="line"><span>SPARKAI_URL = &#39;wss://spark-api.xf-yun.com/v3.5/chat&#39;#星火认知大模型调用秘钥信息，请前往</span></span>
<span class="line"><span>SPARKAI_APP_ID = &#39;&#39;</span></span>
<span class="line"><span>SPARKAI_API_SECRET = &#39;&#39;</span></span>
<span class="line"><span>SPARKAI_API_KEY = &#39;&#39;#星火认知大模型Spark Max的domain值，其他版本大模型domain值请前往文档</span></span>
<span class="line"><span>SPARKAI_DOMAIN = &#39;generalv3.5&#39;if __name__ == &#39;__main__&#39;:</span></span>
<span class="line"><span>   spark = ChatSparkLLM(</span></span>
<span class="line"><span>       spark_api_url=SPARKAI_URL,</span></span>
<span class="line"><span>       spark_app_id=SPARKAI_APP_ID,</span></span>
<span class="line"><span>       spark_api_key=SPARKAI_API_KEY,</span></span>
<span class="line"><span>       spark_api_secret=SPARKAI_API_SECRET,</span></span>
<span class="line"><span>       spark_llm_domain=SPARKAI_DOMAIN,</span></span>
<span class="line"><span>       streaming=False,)</span></span>
<span class="line"><span>   messages = [ChatMessage(</span></span>
<span class="line"><span>       role=&quot;user&quot;,</span></span>
<span class="line"><span>       content=&#39;你好呀&#39;)]</span></span>
<span class="line"><span>   handler = ChunkPrintHandler()</span></span>
<span class="line"><span>   a = spark.generate([messages], callbacks=[handler])</span></span>
<span class="line"><span>   print(a)</span></span>
<span class="line"><span>我说过，大模型是一个全功能的“人”，而代码第 5 行的 /v3.5/chat 这个接口，就可以看作</span></span></code></pre></div><p>跟这个“人”说话。让它干活，这一个接口就够了。</p><p>我们进一步分析一下这个接口的内部请求参数。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 参数构造示例如下</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>       &quot;header&quot;: {</span></span>
<span class="line"><span>           &quot;app_id&quot;: &quot;12345&quot;,</span></span>
<span class="line"><span>           &quot;uid&quot;: &quot;12345&quot;</span></span>
<span class="line"><span>       },</span></span>
<span class="line"><span>       &quot;parameter&quot;: {</span></span>
<span class="line"><span>           &quot;chat&quot;: {</span></span>
<span class="line"><span>               &quot;domain&quot;: &quot;generalv3.5&quot;,</span></span>
<span class="line"><span>               &quot;temperature&quot;: 0.5,</span></span>
<span class="line"><span>               &quot;max_tokens&quot;: 1024,</span></span>
<span class="line"><span>           }</span></span>
<span class="line"><span>       },</span></span>
<span class="line"><span>       &quot;payload&quot;: {</span></span>
<span class="line"><span>           &quot;message&quot;: {</span></span>
<span class="line"><span>               # 如果想获取结合上下文的回答，需要开发者每次将历史问答信息一起传给服务端，如下</span></span>
<span class="line"><span>               # 注意：text里面的所有content内容加一起的tokens需要控制在8192以内，开发者如</span></span>
<span class="line"><span>               &quot;text&quot;: [</span></span>
<span class="line"><span>                   {&quot;role&quot;:&quot;system&quot;,&quot;content&quot;:&quot;你现在扮演李白，你豪情万丈，狂放不羁；接</span></span>
<span class="line"><span>                   {&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: &quot;你是谁&quot;} # 用户的历史问题</span></span>
<span class="line"><span>                   {&quot;role&quot;: &quot;assistant&quot;, &quot;content&quot;: &quot;.....&quot;}  # AI的历史回答结果</span></span>
<span class="line"><span>                   # ....... 省略的历史对话</span></span>
<span class="line"><span>                   {&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: &quot;你会做什么&quot;}  # 最新的一条问题，如无需</span></span>
<span class="line"><span>               ]</span></span>
<span class="line"><span>       }</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>我们关注最主要的几个参数即可。其中最重要的就是第 10 行温度 Temperature 参数。这个参数和大模型的幻觉是相关的，取值范围 0-1。温度越大，大模型创造性越强。有趣的是，现实中即使将温度调到 0，它还是有创造性的，千万不要以为温度设置为 0 大模型就乖乖听话了。</p><p>我们画张图表示下大模型的接口。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/3.png" alt=""></a></p><p>比照互联网架构图中的传统互联网架构，传统架构下的接口是一个分而治之的逻辑，一个接口完成一个专有逻辑。大模型的接口是一个全能逻辑，但却可以实现所有细分的专用能力，具体实现要靠提示词工程。</p><h3 id="提示词工程" tabindex="-1">提示词工程 <a class="header-anchor" href="#提示词工程" aria-label="Permalink to &quot;提示词工程&quot;">​</a></h3><p>我们常说，大模型输出结果的质量好坏取决于输入的质量好坏，这里的输入就是提示词。我们还是以讯飞大模型为例，看下讯飞大模型的输入数据。</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;role&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;system&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;content&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;你现在扮演李白，你豪情万丈，狂放不羁；接下来请用李白的口吻和用户</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">{&quot;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">role</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;: &quot;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;, &quot;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">content</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;: &quot;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">你是谁</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;} # 用户的历史问题</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">{&quot;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">role</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;: &quot;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">assistant</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;, &quot;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">content</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;: &quot;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">.....</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;}  # AI的历史回答结果</span></span></code></pre></div><p>这里的 system，user，assistant 等角色代表什么呢？system 代表就是系统提示词，参数里的你现在扮演李白，你豪情万丈，狂放不羁；接下来请用李白的口吻和用户对话。就是提示词的具体内容，它决定了接下来 AI 在会话中的具体功能。</p><p>大模型接口默认场景是一个 AI 会话，而这个数据里的 user 和 assistant 分别代表了会话里的用户和 AI 机器人这两个角色，有了它们，把会话历史写到参数数据里就很方便了。</p><p>在这个接口里，我们可以调整的是什么呢？其实就是输入的 system 提示词。</p><p>我们用一个大模型执行 SQL 的示例进一步说明提示词的作用。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我给你一个数据表的数据，再给你一个sql，请你给我这个sql的执行结果，</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">数据表 Movies：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Id | Title           | Director       | </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Year</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> | Length_minutes |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">----|-----------------|----------------|------|----------------|</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  | Toy Story       | John Lasseter  | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1995</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">81</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">             |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  | A Bug</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;s Life    | John Lasseter  | 1998 | 95             |</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">| 3  | Toy Story 2     | John Lasseter  | 1999 | 93             |</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">| 4  | Monsters, Inc.  | Pete Docter    | 2001 | 92             |</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">| 5  | Finding Nemo    | Finding Nemo   | 2003 | 107            |</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">| 6  | The Incredibles | Brad Bird      | 2004 | 116            |</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">SQL：</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">select * from movies where year=1998</span></span></code></pre></div><p>上面的提示词给了大模型一个数据表对应的数据，又给了一个 SQL。很多人第一感觉可能会是：啊？大模型能完成这个任务吗？它还能执行 SQL？</p><p>事实上，这个提示词就能让大模型运算并正确输出结果。你可以在自己的大模型环境里尝试一下。我举这个例子只是想说明，大模型就像一个全能的“人”，只要提示词设置得当，它就能完成传统互联网里那些接口的功能。</p><p>当然，要把这些接口正确实现就需要提示词技巧，也就是我们说的提示词工程。从这个角度看，你可以认为大模型是一个全功能的数据库，事实上大模型也正是将整个世界知识压缩到一个很小的参数文件里。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/4.png" alt=""></a></p><p>我们完全可以说，在大模型模式下开发应用，一个提示词就提供了一个接口，写好提示词就是开发好一个接口。</p><p>更进一步来说，未来的所有应用都会基于提示开发，也就是我们日常说的 AI first 的应用。</p><h3 id="逻辑控制" tabindex="-1">逻辑控制 <a class="header-anchor" href="#逻辑控制" aria-label="Permalink to &quot;逻辑控制&quot;">​</a></h3><p>说起来似乎完全用大模型就可以开发出所有应用了，其实则不然。做一个比喻，大模型更像一个文科比较强的人，而传统应用更像一个理科比较强的人。</p><p>就拿前面的 SQL 大模型例子来说，真的要调教出一个执行 SQL 完全不出错的大模型还是很难的，因此大模型和传统架构还是要结合使用。具体来说，有两种大模型应用模式。</p><p>一种是采用会话式交互，AI first 的应用模式。AI first 应用更适合从零开始的创业创新业务。比如一个聊天的 AI 应用，一个客服的 AI 应用，或其他一切基于大模型会话作为基础的应用。这类应用以大模型为中心，同时在必要时结合其他系统的接口（比如天气，计算等）在会话中完成用户的需求。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/5.png" alt=""></a></p><p>另一类则比较简单，这类应用以传统应用为中心，同时结合大模型的能力（比如：翻译，分类），让传统应用加入 AI 能力。这种传统应用开发模式更适合已有成熟业务模式的 AI 升级。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/6.png" alt=""></a></p><h3 id="架构图-v1" tabindex="-1">架构图 V1 <a class="header-anchor" href="#架构图-v1" aria-label="Permalink to &quot;架构图 V1&quot;">​</a></h3><p>好了，现在我们整理一下这些大模型应用的开发模式和传统互联网系统的关系。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/7.png" alt=""></a></p><h2 id="模型微调" tabindex="-1">模型微调 <a class="header-anchor" href="#模型微调" aria-label="Permalink to &quot;模型微调&quot;">​</a></h2><p>如果把 LLM 看做一个全功能、带算法的数据库，那么遇到数据库里没有的数据怎么办呢？这就需要用到大模型微调技术。</p><p>这里说的模型微调和第二节课里大模型训练阶段的微调没有本质的不同，都是用新的训练数据调整大模型的参数，经过微调形成独有的一套参数。还是把 LLM 当做一个全能数据库来说，模型微调，就是复制一份全能数据库，再加入自己的私有表数据。</p><h3 id="什么是微调-fine-tuning" tabindex="-1">什么是微调（Fine-tuning）？ <a class="header-anchor" href="#什么是微调-fine-tuning" aria-label="Permalink to &quot;什么是微调（Fine-tuning）？&quot;">​</a></h3><p>微调大模型的核心工作其实整理数据集，而且是按大模型平台的格式整理。用户要微调大模型得到自己的微调模型，也需要大模型提供微调能力支持，</p><p>举个例子，现在，我要用讯飞星火大模型微调一个春联模型，看一下整体的数据格式。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/8.png" alt=""></a></p><p>我只要把全部的春联数据整理成这 3 段的格式就可以了，我们看看微调前后的效果对比。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/9.png" alt=""></a></p><p>很明显，经过模型微调，春联数据被“注入”到这个大模型里了。你看，将一部分专业私有数据加入大模型，整个大模型就具备了某项专业能力。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/10.png" alt=""></a></p><p>不过别忘了一个词，幻觉。即使我们把私有数据微调注入大模型，大模型还是会在涉及这类数据的时候产生幻觉。如果你想完全避免私有数据的幻觉问题，可以用向量数据库结合大模型开发。</p><h3 id="向量数据库-vs-微调" tabindex="-1">向量数据库 VS 微调 <a class="header-anchor" href="#向量数据库-vs-微调" aria-label="Permalink to &quot;向量数据库 VS 微调&quot;">​</a></h3><p>在工程实践经验看来，向量数据库往往比微调效果还好。</p><p>以一个天气查询的 AI 应用来说明向量数据的应用。比如，现在用户的提问了，问：明天下午纽约的天气如何？</p><p>因为大模型没有实时数据，所以只能是我们查询出实时的天气数据提供给 LLM，让大模型组织语言输出给用户。</p><p>假设我们的天气数据存储在 MySQL 里。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/11.png" alt=""></a></p><p>好，我们需要先查询出明天、纽约、天气相关的数据。但有一个问题，MySQL 没法通过语义查询出数据，而基于向量的向量数据库则可以基于语义查询。这时就需要先将明天下午纽约的天气如何？转化为向量表示，再去向量数据库里查询，就可以按语义相似度查询所有数据。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/12.png" alt=""></a></p><p>注意，这里只是为了更清楚地说明向量数据库的作用，在原 MySQL 表基础上加入这条数据的向量表示，不是实际的向量数据库结构。</p><p>好了，最后把所有可能相关数据交给 LLM，让 LLM 这个“全能人”来根据用户需求回答就可以了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/13.png" alt=""></a></p><h3 id="架构图-v2" tabindex="-1">架构图 V2 <a class="header-anchor" href="#架构图-v2" aria-label="Permalink to &quot;架构图 V2&quot;">​</a></h3><p>加入私有数据的大模型相当于开发出一个私有的数据库，下面的架构图能够辅助你理解。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/14.png" alt=""></a></p><h2 id="专有模型开发" tabindex="-1">专有模型开发 <a class="header-anchor" href="#专有模型开发" aria-label="Permalink to &quot;专有模型开发&quot;">​</a></h2><p>你如果对全能数据库本身不满意，还可以基于开源大模型二次开发，也就是我们说的专有模型开发，例如专门实现代码开发能力的大模型。</p><p>这个基于开源大模型的二次开发，又分为两种情况，偏向行业数据的行业大模型开发，以及偏向大模型能力扩展的大模型插件开发。</p><h3 id="行业大模型" tabindex="-1">行业大模型 <a class="header-anchor" href="#行业大模型" aria-label="Permalink to &quot;行业大模型&quot;">​</a></h3><p>我们知道，ChatGPT 已经具备了很强的编程能力，但是要在代码能力上进一步提升，可以训练一个专门用于开发代码的大模型。</p><p>比如，大型语言模型 Code Llama 可以根据文本提示生成代码。它就是一个专业的代码大模型。Code Llama 支持许多流行语言，包括 Python、C++、Java、PHP、Typescript(Javascript)、C# 和 Bash。</p><p>具体的训练方法和第二节课大模型训练部分以及本节课提到的大模型微调方法是类似的。要训练一个专有大模型重点解决两个问题，一是选用一个开源的基模型，二是制作专用领域的高质量数据集。</p><p>因为 ChatGPT 这类的闭源大模型不能深度定制，所以专有大模型的定制训练和开发一般会选择类似 Llama 这种开源大模型。至于训练的数据，就学 ChatGPT 的方法，用对应领域的高质量数据集就好了。</p><p>还是以我刚才提到的 Code Llama 为例。Code Llama 就是在 Llama 开源大模型的基础上开发的，用了 500B 代码 token 和代码相关数据进行训练。后续的课程案例也会有更多专有大模型的训练细节，我这里就简单介绍一下。接下来跟你说说插件开发。</p><h3 id="插件开发" tabindex="-1">插件开发 <a class="header-anchor" href="#插件开发" aria-label="Permalink to &quot;插件开发&quot;">​</a></h3><p>如果要给自己的专用大模型增加一个算法能力，比如互联网搜索、代码执行等，需要修改大模型推理部分的代码，也就是我们平常说的大模型插件开发，一个插件对应一个专有的功能。</p><p>比如用户输入：帮我搜索 XX 信息，并根据这个信息来回答问题。</p><p>显然大模型应该有能力识别用户的意图，并且在它自己的输出中标识出用户的意图，不然就没有机会调用搜索程序了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/15.png" alt=""></a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你看，图中的 search_page 就是大模型意图识别后给我们返回的标识，这表明大模型需要</span></span>
<span class="line"><span>我们的专有程序去处理 search_page 任务，获取数据后再次提交给大模型处理用户请求。</span></span></code></pre></div><p>现在的问题就变成了如何让大模型具备识别这些意图的能力。答案还是大模型数据微调。我们需要用类似下面的意图判断实例数据对大模型进行训练，大模型就会具备这类意图识别能力了。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;查找关于GPT-4的最新研究论文&quot; -&gt; &quot;search_paper&quot;</span></span>
<span class="line"><span>&quot;天气怎么样&quot; -&gt; &quot;weather_query&quot;</span></span>
<span class="line"><span>&quot;给我讲个笑话&quot; -&gt; &quot;tell_joke&quot;</span></span>
<span class="line"><span>&quot;搜索一个网页&quot; -&gt; &quot;search_page&quot;</span></span>
<span class="line"><span>... ...</span></span></code></pre></div><h3 id="架构图v3" tabindex="-1">架构图V3 <a class="header-anchor" href="#架构图v3" aria-label="Permalink to &quot;架构图V3&quot;">​</a></h3><p>专有模型相当于全能数据库的二次开发，以及全能数据库自定义函数的开发。下面整理一个完整的大模型应用开发工程架构图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/16.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/16.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/17.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/17.png" alt=""></a></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>回顾一下最终整理的大模型 AI 智能体应用开发架构图，我们会发现传统互联网架构、传统应用、大模型、提示词、微调、AI first 应用之间的关系其实是比较清晰的。从分层的角度对比来看，AI 大模型和数据库是一层的，提示词和传统接口是一层的，AI 应用属于应用层。</p><p>类比传统应用架构来理解 AI 应用会更清晰。</p><p>现在让我们回顾第一、第二节课的内容，梳理一下 Transformer、大模型、微调以及应用开发的关系。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/18.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/04/18.png" alt=""></a></p><p>未来的大部分应用都将是 AI first 的，但是传统应用框架下现有的能力和开发方法同样重要。如果对照传统开发框架来说，提示词就是新时代的接口程序，LLM 就是集合了现有世界知识的全能数据库，而专有 LLM 则是一个行业专有数据库。</p><p>当然，最终的应用往往需要在专有 LLM 或公有 LLM 基础上结合私有数据微调，同时结合已有的应用接口整合出一个可靠的 AI 应用，避免大模型那些出错的“幻觉”，留下我们需要的创造性。</p><p>具体怎么做呢？我想接下来的项目实战课程会给出更细的答案。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>在大模型 AI 智能体开发中，哪些功能用 LLM 实现，哪些功能用传统程序接口实现呢？如何选择？有什么评判标准吗？</p><p>欢迎你在留言区和我交流。如果觉得有所收获，也可以把课程分享给更多的朋友一起学习。我们下节课见！</p><blockquote><blockquote><p>戳此加入课程交流群</p></blockquote></blockquote>`,105)])])}const g=a(i,[["render",p]]);export{c as __pageData,g as default};
